<?php
$selectedCode=(string)($entry['cost_code_id']??'');
$selectedSection='';
foreach($codes as $code)if((string)$code['id']===$selectedCode)$selectedSection=(string)$code['work_section_id'];
$expenseType=$entry['expense_type']??'work';
?>
<div class="col-md-4"><label class="form-label fw-bold required" for="expense-type">نوع المصروف</label><select class="form-select js-tom-select" id="expense-type" name="expense_type" required><option value="work" <?=$expenseType==='work'?'selected':''?>>مصروف بند أعمال</option><option value="general" <?=$expenseType==='general'?'selected':''?>>مصروف عام</option></select></div>
<div class="col-md-4" id="cost-section-field"><label class="form-label fw-bold required" for="cost-section">البند الرئيسي</label><select class="form-select js-tom-select" id="cost-section" name="cost_section_id"><option value="">اختر البند الرئيسي</option><?php foreach($sections as $section):?><option value="<?=(int)$section['id']?>" <?=$selectedSection===(string)$section['id']?'selected':''?>><?=e($section['section_code'].' — '.$section['name'])?></option><?php endforeach;?></select></div>
<div class="col-md-4"><label class="form-label fw-bold required" id="expense-code-label" for="project-cost-code">البند الفرعي</label><div class="input-group"><select class="form-select js-tom-select" id="project-cost-code" name="cost_code_id" data-placeholder="اختر البند الفرعي" data-hide-empty-option="true" required><option value="">اختر البند الفرعي</option><?php foreach($codes as $code):if((!$code['is_active']||!$code['section_active'])&&$selectedCode!==(string)$code['id'])continue;?><option value="<?=(int)$code['id']?>" data-section="<?=(int)$code['work_section_id']?>" data-section-name="<?=e($code['section_name'])?>" <?=$selectedCode===(string)$code['id']?'selected':''?>><?=e($code['cost_code'].' — '.$code['name'])?></option><?php endforeach;?></select><?php if($canManageCostStructure??false):?><button class="btn btn-outline-primary" type="button" id="add-expense-code" title="إضافة بند فرعي تحت البند الرئيسي المختار" aria-label="إضافة بند فرعي" disabled><i class="ti ti-plus" aria-hidden="true"></i></button><?php endif;?></div><div class="form-hint">يُستخدم اسم البند وصفًا للمصروف تلقائيًا.</div></div>
